import { writeFileSync } from 'node:fs';
import { clientStatements, type Schema } from '@sync-engine/core';

const swiftFile = (schema: Schema, statements: string[]) => {
	const tables = schema.tables.map(({ name, columns }) => {
		const names = columns.filter(c => c.name !== 'id').map(c => JSON.stringify(c.name));
		return `        SyncTable(name: ${JSON.stringify(name)}, columns: [${names.join(', ')}]),`;
	});
	return [
		'// Generated by sync-engine. Do not edit.',
		'import SyncEngine',
		'',
		'let syncSchema = SyncSchema(',
		'    tables: [',
		...tables,
		'    ],',
		'    statements: [',
		...statements.map(sql => `        ${JSON.stringify(sql)},`),
		'    ]',
		')',
		'',
	].join('\n');
};

export function generate({ schema, swift, ddl }: { schema: Schema; swift?: string; ddl?: string }): {
	swift: string;
	ddl: string;
} {
	const statements = clientStatements(schema);
	const out = { swift: swiftFile(schema, statements), ddl: statements.map(sql => `${sql};\n`).join('') };
	if (swift) writeFileSync(swift, out.swift);
	if (ddl) writeFileSync(ddl, out.ddl);
	return out;
}
